// Controller: one FSM state per schedule step.
// Generated by the EC551 HLS tool from pdf_example.txt (asap schedule,
// 3 steps). Do not edit: rerun the tool instead.
module hls_controller (
    input  wire clk,
    input  wire rst,
    input  wire en,
    input  wire start,
    input  wire restart,
    output reg  [7:0] state,
    output wire done,
    output reg  [11:0] fu_active,
    output reg  add0_b_sel,
    output reg  r0_we,
    output reg  r1_we,
    output reg  r2_we,
    output reg  r3_we
);

    localparam IDLE = 8'd0;
    localparam DONE = 8'd4;

    assign done = (state == DONE);

    // IDLE -> step 1 -> ... -> last step -> DONE, one state per enabled edge.
    always @(posedge clk) begin
        if (rst || restart)
            state <= IDLE;
        else if (en) begin
            case (state)
                IDLE: if (start) state <= 8'd1;
                DONE: state <= DONE;
                default: state <= state + 8'd1;
            endcase
        end
    end

    // Control signals for each state. Anything not set here is 0.
    always @* begin
        fu_active = 12'd0;
        add0_b_sel = 1'd0;
        r0_we = 1'd0;
        r1_we = 1'd0;
        r2_we = 1'd0;
        r3_we = 1'd0;
        case (state)
            8'd1: begin
                // add0 = A + B -> r0  (X_1 = A_0 + B_0)
                add0_b_sel = 1'd0;
                r0_we = 1'd1;
                fu_active = 12'b000000000001;
            end
            8'd2: begin
                // add0 = A + r0 -> r1  (Y_1 = X_1 + A_0)
                // sub0 = r0 - B -> r2  (Z_1 = X_1 - B_0)
                add0_b_sel = 1'd1;
                r1_we = 1'd1;
                r2_we = 1'd1;
                fu_active = 12'b000000000011;
            end
            8'd3: begin
                // mul0 = B * r2 -> r3  (Q_1 = B_0 * Z_1)
                r3_we = 1'd1;
                fu_active = 12'b000000000100;
            end
            default: ;
        endcase
    end
endmodule
